CREATE TABLE IF NOT EXISTS society_amenities(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,description VARCHAR(500) NULL,capacity INT UNSIGNED NOT NULL DEFAULT 1,is_bookable BOOLEAN NOT NULL DEFAULT TRUE,requires_approval BOOLEAN NOT NULL DEFAULT TRUE,hourly_charge DECIMAL(10,2) NOT NULL DEFAULT 0,opening_time TIME NULL,closing_time TIME NULL,status ENUM('ACTIVE','INACTIVE','MAINTENANCE') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uk_amenity_name(society_id,name),CONSTRAINT fk_amenity_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS amenity_time_slots(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,amenity_id BIGINT UNSIGNED NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,max_bookings INT UNSIGNED NOT NULL DEFAULT 1,charge_amount DECIMAL(10,2) NOT NULL DEFAULT 0,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_amenity_slot(amenity_id,start_time,end_time),CONSTRAINT fk_slot_amenity FOREIGN KEY(amenity_id) REFERENCES society_amenities(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_amenity_slot_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS amenity_bookings(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,society_id BIGINT UNSIGNED NOT NULL,booking_number VARCHAR(50) NOT NULL,amenity_id BIGINT UNSIGNED NOT NULL,slot_id BIGINT UNSIGNED NOT NULL,flat_id BIGINT UNSIGNED NOT NULL,member_id BIGINT UNSIGNED NULL,booking_date DATE NOT NULL,purpose VARCHAR(300) NULL,attendee_count INT UNSIGNED NOT NULL DEFAULT 1,amount DECIMAL(10,2) NOT NULL DEFAULT 0,status ENUM('PENDING','APPROVED','REJECTED','CANCELLED','COMPLETED') NOT NULL DEFAULT 'PENDING',decision_note VARCHAR(500) NULL,approved_by BIGINT UNSIGNED NULL,approved_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_booking_number(society_id,booking_number),KEY idx_booking_slot_date(society_id,slot_id,booking_date,status),KEY idx_booking_flat(society_id,flat_id,booking_date),CONSTRAINT fk_booking_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_booking_amenity FOREIGN KEY(amenity_id) REFERENCES society_amenities(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_booking_slot FOREIGN KEY(slot_id) REFERENCES amenity_time_slots(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_booking_flat FOREIGN KEY(flat_id) REFERENCES flats(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_booking_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL ON UPDATE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS amenity_booking_sequences(society_id BIGINT UNSIGNED PRIMARY KEY,next_number BIGINT UNSIGNED NOT NULL DEFAULT 1,CONSTRAINT fk_amenity_seq_society FOREIGN KEY(society_id) REFERENCES societies(id) ON DELETE RESTRICT ON UPDATE CASCADE)ENGINE=InnoDB;
INSERT INTO permissions(permission_name,permission_code,module_name,description,status)VALUES('View Amenities','society.amenities.view','amenities','View amenities and bookings','ACTIVE'),('Manage Amenities','society.amenities.manage','amenities','Manage amenities and slots','ACTIVE'),('Book Amenities','society.amenities.book','amenities','Create and cancel own bookings','ACTIVE'),('Approve Amenity Bookings','society.amenities.approve','amenities','Approve or reject amenity bookings','ACTIVE')ON DUPLICATE KEY UPDATE status='ACTIVE';
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_code IN('SUPER_ADMIN','SOCIETY_ADMIN','CHAIRMAN','SECRETARY')AND p.permission_code LIKE'society.amenities.%' ON DUPLICATE KEY UPDATE permission_id=VALUES(permission_id);INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_code IN('TREASURER','ACCOUNTANT','SECURITY','RESIDENT')AND p.permission_code IN('society.amenities.view','society.amenities.book')ON DUPLICATE KEY UPDATE permission_id=VALUES(permission_id);
